def build():
    tr, en = dict(TR), dict(EN)
    for k, (tn, td, en_n, ed) in MOVES.items():
        tr[f"move.{P}.{k}"] = tn
        tr[f"move.{P}.{k}.desc"] = td
        en[f"move.{P}.{k}"] = en_n
        en[f"move.{P}.{k}.desc"] = ed
    for k, (t, e) in SOUNDS.items():
        tr[f"subtitles.{P}.{k}"] = t
        en[f"subtitles.{P}.{k}"] = e
    os.makedirs(A, exist_ok=True)
    for name, d in (("tr_tr", tr), ("en_us", en)):
        with open(os.path.join(A, name + ".json"), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=1)
    return tr, en


if __name__ == '__main__':
    tr, en = build()
    print(len(tr), len(en))
